//! Golden tests: core decoders vs. the Python reference (`ptiles/*.py`),
//! generated by `test-fixtures/extract_golden.py` into
//! `test-fixtures/golden/<layer>.{block.bin,golden.json,meta.json}`.
//!
//! Field-by-field comparison against `serde_json::Value`, tolerant of
//! float noise (1e-9 abs/rel) since the Python side round-trips through
//! `round()`/tuple construction that can differ in the last bit from
//! Rust's `f64` arithmetic on the same inputs.

use serde_json::{json, Value};
use std::fs;
use std::path::PathBuf;

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("test-fixtures")
        .join("golden")
}

fn load_block(layer: &str) -> Vec<u8> {
    fs::read(fixture_dir().join(format!("{layer}.block.bin")))
        .unwrap_or_else(|e| panic!("failed to read {layer}.block.bin: {e}"))
}

fn load_golden(layer: &str) -> Value {
    let text = fs::read_to_string(fixture_dir().join(format!("{layer}.golden.json")))
        .unwrap_or_else(|e| panic!("failed to read {layer}.golden.json: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("failed to parse {layer}.golden.json: {e}"))
}

fn load_meta(layer: &str) -> Value {
    let text = fs::read_to_string(fixture_dir().join(format!("{layer}.meta.json")))
        .unwrap_or_else(|e| panic!("failed to read {layer}.meta.json: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("failed to parse {layer}.meta.json: {e}"))
}

/// Recursively compare two JSON values, tolerating float noise. Panics with
/// a path-annotated message on the first mismatch found.
fn assert_json_eq(actual: &Value, expected: &Value, path: &str) {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            let (af, ef) = (a.as_f64().unwrap(), e.as_f64().unwrap());
            let tol = 1e-9_f64.max(ef.abs() * 1e-9);
            assert!(
                (af - ef).abs() <= tol,
                "{path}: number mismatch: actual={af} expected={ef}"
            );
        }
        (Value::Array(a), Value::Array(e)) => {
            assert_eq!(
                a.len(),
                e.len(),
                "{path}: array length mismatch: actual={} expected={}",
                a.len(),
                e.len()
            );
            for (i, (av, ev)) in a.iter().zip(e.iter()).enumerate() {
                assert_json_eq(av, ev, &format!("{path}[{i}]"));
            }
        }
        (Value::Object(a), Value::Object(e)) => {
            let mut a_keys: Vec<_> = a.keys().collect();
            let mut e_keys: Vec<_> = e.keys().collect();
            a_keys.sort();
            e_keys.sort();
            assert_eq!(a_keys, e_keys, "{path}: object key set mismatch");
            for k in e.keys() {
                assert_json_eq(&a[k], &e[k], &format!("{path}.{k}"));
            }
        }
        (a, e) => {
            assert_eq!(a, e, "{path}: value mismatch");
        }
    }
}

#[test]
fn water_golden() {
    let block = load_block("water");
    let golden = load_golden("water");
    let features = ptiles_core::decode_water(&block).expect("decode_water failed");

    let actual = json!({
        "features": features.iter().map(|f| json!({
            "osm_id": f.osm_id,
            "geom_type": match f.geom_type { 0 => "polygon", 1 => "linestring", 2 => "reference", _ => "unknown" },
            "water_type": f.water_type,
            "coords": f.coords,
            "ref_feature_id": f.ref_feature_id,
            "name": f.name,
            "width": f.width,
            "vertex_count": f.coords.len(),
        })).collect::<Vec<_>>(),
    });

    assert_json_eq(&actual, &golden, "water");
}

