#[test]
fn roads_golden() {
    let block = load_block("roads");
    let golden = load_golden("roads");
    let meta = load_meta("roads");
    let version = meta["file_version"].as_u64().unwrap() as u8;

    let (roads, intersections) =
        ptiles_core::decode_road_block(&block, version).expect("decode_road_block failed");

    let actual = json!({
        "roads": roads.iter().map(|r| json!({
            "osm_id": r.osm_id,
            "road_class": r.road_class,
            "coords": r.coords,
            "name": r.name,
            "ref_tag": r.ref_tag,
            "oneway": r.oneway,
            "speed_limit_kmh": r.speed_limit_kmh,
            "lanes": r.lanes,
            "surface": r.surface,
            "bridge_tunnel": r.bridge_tunnel,
        })).collect::<Vec<_>>(),
        "intersections": intersections.iter().map(|i| json!({
            "lon_micro": i.lon_micro,
            "lat_micro": i.lat_micro,
            "intersection_type": i.intersection_type,
        })).collect::<Vec<_>>(),
    });

    assert_json_eq(&actual, &golden, "roads");
}

#[test]
fn buildings_v8_golden() {
    let block = load_block("buildings_v8");
    let golden = load_golden("buildings_v8");
    let meta = load_meta("buildings_v8");
    let cell_center_lat = meta["cell_center_lat"].as_f64().unwrap();
    let cell_center_lon = meta["cell_center_lon"].as_f64().unwrap();

    let buildings = ptiles_core::decode_buildings(&block, cell_center_lat, cell_center_lon)
        .expect("decode_buildings failed");

    let actual = json!({
        "buildings": buildings.iter().map(|b| json!({
            "osm_id": b.osm_id,
            "building_type": b.building_type,
            "centroid_lat": b.centroid_lat,
            "centroid_lon": b.centroid_lon,
            "coordinates": b.coords,
            "name": b.name,
            "category": b.category,
            "name_source": b.name_source,
            "poi_osm_id": b.poi_osm_id,
        })).collect::<Vec<_>>(),
    });

    assert_json_eq(&actual, &golden, "buildings_v8");
}

